@extends('layouts.app') @section('title','မွေးစားရန် တိရစ္ဆာန်များ') @section('content')<div class="mb-8"><h1 class="text-3xl font-bold">အိမ်အသစ်စောင့်နေသော မိတ်ဆွေများ</h1><p class="mt-2 text-slate-600">တာဝန်ယူမှုအပြည့်ဖြင့် မွေးစားပေးနိုင်မည့် မိသားစုကို ရှာဖွေနေပါသည်။</p></div><form class="mb-8 grid gap-3 rounded-xl bg-white p-5 shadow-sm sm:grid-cols-5"><select name="animal_type" class="rounded border p-2"><option value="">အမျိုးအစားအားလုံး</option><option value="dog" @selected(request('animal_type')==='dog')>ခွေး</option><option value="cat" @selected(request('animal_type')==='cat')>ကြောင်</option></select><select name="breed" class="rounded border p-2"><option value="">မျိုးစိတ်အားလုံး</option>@foreach($breeds as $breed)<option @selected(request('breed')===$breed)>{{ $breed }}</option>@endforeach</select><select name="age_group" class="rounded border p-2"><option value="">အသက်အားလုံး</option>@foreach(['baby'=>'ကလေး','young'=>'ငယ်ရွယ်','adult'=>'အရွယ်ရောက်','senior'=>'အသက်ကြီး'] as $v=>$l)<option value="{{ $v }}" @selected(request('age_group')===$v)>{{ $l }}</option>@endforeach</select><select name="gender" class="rounded border p-2"><option value="">လိင်အားလုံး</option><option value="male">အထီး</option><option value="female">အမ</option></select><button class="rounded bg-emerald-700 px-4 py-2 text-white">ရှာမည်</button></form><div class="grid gap-6 sm:grid-cols-2 lg:grid-cols-3">@forelse($pets as $pet)<a href="{{ route('pets.show',$pet) }}" class="overflow-hidden rounded-xl bg-white shadow-sm transition hover:shadow-lg">@if($pet->primaryImage)<img src="{{ str_starts_with($pet->primaryImage->path, 'http') ? $pet->primaryImage->path : asset('storage/'.$pet->primaryImage->path) }}" class="h-56 w-full object-cover" alt="{{ $pet->name }}">@else<div class="grid h-56 place-items-center bg-slate-200 text-5xl">🐾</div>@endif<div class="p-5"><div class="flex justify-between"><h2 class="text-xl font-bold">{{ $pet->name }}</h2><span class="rounded-full bg-emerald-100 px-3 py-1 text-xs text-emerald-800">{{ ucfirst($pet->status) }}</span></div><p class="mt-2 text-sm text-slate-500">{{ $pet->animal_type==='dog'?'ခွေး':'ကြောင်' }} · {{ $pet->breed ?: 'မျိုးစိတ်မသိ' }} · {{ ucfirst($pet->gender) }}</p></div></a>@empty<p>ရှာဖွေမှုနှင့်ကိုက်ညီသည့် မှတ်တမ်းမရှိပါ။</p>@endforelse</div><div class="mt-8">{{ $pets->links() }}</div>@endsection
